<template><section class="draft-preview"><el-radio-group v-model="mode" size="small"><el-radio-button value="stem">题干</el-radio-button><el-radio-button value="stem-answer">题干 + 答案</el-radio-button><el-radio-button value="stem-analysis">题干 + 解析</el-radio-button><el-radio-button value="all">题干 + 答案 + 解析</el-radio-button></el-radio-group><article v-for="section in visibleSections" :key="section" class="preview-section"><h3>{{labels[section]}}</h3><template v-for="block in draft.sections[section].blocks" :key="block.id"><div v-if="block.kind==='text'" class="markdown-body" v-html="renderMarkdown(block.markdown)"></div><QuestionImageAreaCanvas v-else :area="block" :url-for="urlFor" /></template><el-empty v-if="!draft.sections[section].blocks.length" description="暂无内容" :image-size="48" /></article></section></template>
<script setup>
import{computed,ref}from'vue';import{renderMarkdown}from'@/utils/renderMarkdown';import QuestionImageAreaCanvas from './QuestionImageAreaCanvas.vue'
defineProps({draft:{type:Object,required:true},urlFor:{type:Function,required:true}});const mode=ref('all');const labels={stem:'题干',answer:'答案',analysis:'解析'};const visibleSections=computed(()=>mode.value==='stem'?['stem']:mode.value==='stem-answer'?['stem','answer']:mode.value==='stem-analysis'?['stem','analysis']:['stem','answer','analysis'])
</script>
<style scoped>.draft-preview{display:grid;gap:12px}.preview-section{padding:12px;border:1px solid #dcdfe6;border-radius:8px}.preview-section h3{margin-top:0}</style>
